function monthlyPayment(principal, annualRate, months){
  var r=annualRate/12;
  if(r===0) return principal/months;
  return principal*r/(1-Math.pow(1+r,-months));
}
function schedule(principal, annualRate, months, method){
  method=method||'equal';
  var r=annualRate/12; var rows=[]; var bal=principal;
  if(method==='equal'){
    var pmt=monthlyPayment(principal,annualRate,months);
    for(var m=1;m<=months;m++){var interest=bal*r;var princ=pmt-interest;bal-=princ;if(m===months)bal=0;
      rows.push({month:m,payment:pmt,interest:interest,principal:princ,balance:Math.max(0,bal)});}
  } else {
    var princ0=principal/months;
    for(var m2=1;m2<=months;m2++){var interest2=bal*r;var pmt2=princ0+interest2;bal-=princ0;if(m2===months)bal=0;
      rows.push({month:m2,payment:pmt2,interest:interest2,principal:princ0,balance:Math.max(0,bal)});}
  }
  return rows;
}
function totalInterest(principal,annualRate,months,method){var s=schedule(principal,annualRate,months,method);var t=0;for(var i=0;i<s.length;i++)t+=s[i].interest;return t;}
var EXPORTS={monthlyPayment:monthlyPayment,schedule:schedule,totalInterest:totalInterest};


